#include <bits/stdc++.h>using namespace std;  int get_odd(int n) {    while (n % 2 == 0) {        n /= 2;    }    return n;} void solve() {    int n;    cin >> n;    vector<int> a(n + 1);    bool ok = true;     for (int i = 1; i <= n; ++i) {        cin >> a[i];    }     for (int i = 1; i <= n; ++i) {        if (get_odd(a[i]) != get_odd(i)) {            ok = false;        }    }     if (ok) cout << "YES\n";    else cout << "NO\n";} int main() {    ios_base::sync_with_stdio(false);    cin.tie(NULL);    int t;    if (cin >> t) {        while (t--) {            solve();        }    }    return 0;}